contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);
        require(amount1 > 0);
        require(amount2 > 0);

        uint bal0 = address(c).balance;
        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        uint bal1 = address(c).balance;
        require(bal1 == bal0 + amount1);

        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        uint bal2 = address(c).balance;
        require(bal2 == bal1 + amount2);

        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool creditExceedsBalance = (amount1 + amount2) > contractBalanceBefore;

        assert(reverted == creditExceedsBalance);
    }

    receive() external payable {}
}

