// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        uint bal0 = address(c).balance;
        try c.deposit{value: amount1}() {} catch { return; }
        uint bal1 = address(c).balance;
        vm.assume(bal1 == bal0 + amount1);
        try c.deposit{value: amount2}() {} catch { return; }
        uint bal2 = address(c).balance;
        vm.assume(bal2 == bal1 + amount2);
        uint contractBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        bool creditExceedsBalance = (amount1 + amount2) > contractBalanceBefore;
        assertTrue(reverted == creditExceedsBalance);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
